import torch
import torch.nn as nn
from torch.nn.modules.utils import _triple
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                       torch::Tensor weight,
                                       c10::optional<torch::Tensor> bias,
                                       int64_t stride,
                                       int64_t padding,
                                       int64_t output_padding,
                                       int64_t groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled ConvTranspose3d kernel for stride=1, dilation=1, groups=1.
// With stride 1, transposed convolution is a "full" convolution:
//   out[n,o,d,h,w] = sum_i sum_{kd,kh,kw} x[n,i,d+pad-kd,h+pad-kh,w+pad-kw] * wt[i,o,kd,kh,kw]
// Each thread block computes a (TD x TH x TW) tile of outputs for OC_TILE output
// channels of one batch. The input tile (with K-1 halo) and the weights are
// staged in shared memory using CuTe tensors, and reused across all OC_TILE
// output channels.
template <int K>
__global__ void __launch_bounds__(256)
conv_transpose3d_s1_kernel(
    const float* __restrict__ Xp,
    const float* __restrict__ Wp,
    const float* __restrict__ Bp,
    float* __restrict__ Yp,
    int C_in, int C_out,
    int D, int H, int W,
    int Dout, int Hout, int Wout,
    int padding)
{
  constexpr int TD = 4, TH = 8, TW = 16;      // output tile; W is register-blocked 2-wide
  constexpr int RB_W = 2;                     // outputs per thread along W
  constexpr int TWT = TW / RB_W;              // thread columns along W
  constexpr int THREADS = TD * TH * TWT;      // 256
  static_assert(TW % RB_W == 0, "TW must be divisible by RB_W");
  constexpr int SD = TD + K - 1;
  constexpr int SH = TH + K - 1;
  constexpr int SW = TW + K - 1;
  constexpr int OC_TILE = (K <= 6 ? 16 : 8);
  constexpr int K2 = K * K;
  constexpr int K3 = K * K * K;
  const int tid = threadIdx.x;
  const int n   = blockIdx.z;
  const int oc0 = blockIdx.y * OC_TILE;
  // Decompose blockIdx.x into spatial tile coordinates
  const int tilesW = (Wout + TW - 1) / TW;
  const int tilesH = (Hout + TH - 1) / TH;
  const int tlin = blockIdx.x;
  const int twi  = tlin % tilesW;
  const int thi  = (tlin / tilesW) % tilesH;
  const int tdi  = tlin / (tilesW * tilesH);
  const int d0 = tdi * TD;
  const int h0 = thi * TH;
  const int w0 = twi * TW;
  // Thread's local coordinates inside the output tile. Each thread owns
  // RB_W adjacent outputs along W, so one shared weight value feeds RB_W FMAs.
  const int td  = tid / (TH * TWT);
  const int th  = (tid / TWT) % TH;
  const int tw  = tid % TWT;
  const int lw0 = tw * RB_W;
  // Global CuTe tensors (per-batch views)
  const int64_t sxn = (int64_t)C_in * D * H * W;
  Tensor mX = make_tensor(make_gmem_ptr(Xp + n * sxn),
      make_shape(C_in, D, H, W),
      make_stride((int64_t)D * H * W, (int64_t)H * W, (int64_t)W, Int<1>{}));
  Tensor mW = make_tensor(make_gmem_ptr(Wp),
      make_shape(C_in, C_out, Int<K>{}, Int<K>{}, Int<K>{}),
      make_stride((int64_t)C_out * K3, (int64_t)K3, Int<K2>{}, Int<K>{}, Int<1>{}));
  const int64_t syn = (int64_t)C_out * Dout * Hout * Wout;
  Tensor mY = make_tensor(make_gmem_ptr(Yp + n * syn),
      make_shape(C_out, Dout, Hout, Wout),
      make_stride((int64_t)Dout * Hout * Wout, (int64_t)Hout * Wout, (int64_t)Wout, Int<1>{}));
  // Double-buffered shared memory tiles for pipelined staging
  __shared__ float sX_raw[2 * SD * SH * SW];
  __shared__ float sW_raw[2 * OC_TILE * K3];
  auto sX_layout = make_layout(make_shape(Int<SD>{}, Int<SH>{}, Int<SW>{}),
                               make_stride(Int<SH * SW>{}, Int<SW>{}, Int<1>{}));
  auto sW_layout = make_layout(make_shape(Int<OC_TILE>{}, Int<K3>{}),
                               make_stride(Int<K3>{}, Int<1>{}));
  auto make_sX = [&](int buf) {
    return make_tensor(make_smem_ptr(sX_raw + buf * (SD * SH * SW)), sX_layout);
  };
  auto make_sW = [&](int buf) {
    return make_tensor(make_smem_ptr(sW_raw + buf * (OC_TILE * K3)), sW_layout);
  };
  // Accumulators (OC_TILE channels x RB_W adjacent W outputs), initialized with bias
  float acc[OC_TILE][RB_W];
  #pragma unroll
  for (int o = 0; o < OC_TILE; ++o) {
    const float bv = (Bp != nullptr && (oc0 + o) < C_out) ? Bp[oc0 + o] : 0.0f;
    #pragma unroll
    for (int r = 0; r < RB_W; ++r) {
      acc[o][r] = bv;
    }
  }
  // Lower corner of the input halo region backing this output tile
  const int base_d = d0 + padding - (K - 1);
  const int base_h = h0 + padding - (K - 1);
  const int base_w = w0 + padding - (K - 1);
  // Stage weights (ic, oc0..oc0+OC_TILE) and the haloed input tile for
  // input channel ic into shared-memory buffer `buf` (zero-filled outside).
  auto stage_tile = [&](int ic, int buf) {
    Tensor sW = make_sW(buf);
    #pragma unroll
    for (int o = 0; o < OC_TILE; ++o) {
      const int oc = oc0 + o;
      for (int k = tid; k < K3; k += THREADS) {
        float wv = 0.0f;
        if (oc < C_out) {
          int kd = k / K2;
          int r  = k - kd * K2;
          int kh = r / K;
          int kw = r - kh * K;
          wv = mW(ic, oc, kd, kh, kw);
        }
        sW(o, k) = wv;
      }
    }
    Tensor sX = make_sX(buf);
    for (int idx = tid; idx < SD * SH * SW; idx += THREADS) {
      int ld  = idx / (SH * SW);
      int rem = idx - ld * (SH * SW);
      int lh  = rem / SW;
      int lw  = rem - lh * SW;
      int gd = base_d + ld;
      int gh = base_h + lh;
      int gw = base_w + lw;
      float v = 0.0f;
      if ((unsigned)gd < (unsigned)D &&
          (unsigned)gh < (unsigned)H &&
          (unsigned)gw < (unsigned)W) {
        v = mX(ic, gd, gh, gw);
      }
      sX(ld, lh, lw) = v;
    }
  };
  // Pipelined main loop: prefetch the next input-channel tile into the
  // idle buffer while accumulating from the current one (one barrier/step).
  stage_tile(0, 0);
  __syncthreads();
  for (int ic = 0; ic < C_in; ++ic) {
    const int cur = ic & 1;
    if (ic + 1 < C_in) {
      stage_tile(ic + 1, cur ^ 1);
    }
    Tensor sX = make_sX(cur);
    Tensor sW = make_sW(cur);
    // Accumulate over the K^3 taps from shared memory. For each tap, load the
    // OC_TILE weights once and reuse them for RB_W neighboring W outputs.
    #pragma unroll
    for (int kd = 0; kd < K; ++kd) {
      const int sxd = td + (K - 1 - kd);
      #pragma unroll
      for (int kh = 0; kh < K; ++kh) {
        const int sxh = th + (K - 1 - kh);
        #pragma unroll
        for (int kw = 0; kw < K; ++kw) {
          const int sxw0 = lw0 + (K - 1 - kw);
          const float xv0 = sX(sxd, sxh, sxw0);
          const float xv1 = sX(sxd, sxh, sxw0 + 1);
          const int kk = (kd * K + kh) * K + kw;
          #pragma unroll
          for (int o = 0; o < OC_TILE; ++o) {
            const float wv = sW(o, kk);
            acc[o][0] = fmaf(xv0, wv, acc[o][0]);
            acc[o][1] = fmaf(xv1, wv, acc[o][1]);
          }
        }
      }
    }
    __syncthreads();
  }
  // Epilogue: guarded stores for the RB_W outputs owned by this thread
  const int gd = d0 + td;
  const int gh = h0 + th;
  if (gd < Dout && gh < Hout) {
    #pragma unroll
    for (int r = 0; r < RB_W; ++r) {
      const int gw = w0 + lw0 + r;
      if (gw < Wout) {
        #pragma unroll
        for (int o = 0; o < OC_TILE; ++o) {
          const int oc = oc0 + o;
          if (oc < C_out) {
            mY(oc, gd, gh, gw) = acc[o][r];
          }
        }
      }
    }
  }
}
template <int K>
static void launch_conv_transpose3d_s1(
    const float* x, const float* w, const float* b, float* y,
    int N, int C_in, int C_out,
    int D, int H, int W,
    int Dout, int Hout, int Wout,
    int padding, cudaStream_t stream)
{
  constexpr int TD = 4, TH = 8, TW = 16;
  constexpr int OC_TILE = (K <= 6 ? 16 : 8);
  const unsigned tiles =
      (unsigned)((Dout + TD - 1) / TD) *
      (unsigned)((Hout + TH - 1) / TH) *
      (unsigned)((Wout + TW - 1) / TW);
  dim3 grid(tiles, (unsigned)((C_out + OC_TILE - 1) / OC_TILE), (unsigned)N);
  dim3 block(256);
  conv_transpose3d_s1_kernel<K><<<grid, block, 0, stream>>>(
      x, w, b, y, C_in, C_out, D, H, W, Dout, Hout, Wout, padding);
}

torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                       torch::Tensor weight,
                                       c10::optional<torch::Tensor> bias,
                                       int64_t stride,
                                       int64_t padding,
                                       int64_t output_padding,
                                       int64_t groups) {
  TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
              "x and weight must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, C_in, D, H, W]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [C_in, C_out, K, K, K]");
  TORCH_CHECK(stride == 1, "Only stride=1 is supported by this kernel");
  TORCH_CHECK(output_padding == 0, "Only output_padding=0 is supported by this kernel");
  TORCH_CHECK(groups == 1, "Only groups=1 is supported by this kernel");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  const int64_t N    = x.size(0);
  const int64_t C_in = x.size(1);
  const int64_t D    = x.size(2);
  const int64_t H    = x.size(3);
  const int64_t W    = x.size(4);

  TORCH_CHECK(weight.size(0) == C_in, "weight.size(0) must equal in_channels");
  const int64_t C_out = weight.size(1);
  const int64_t Kd = weight.size(2);
  const int64_t Kh = weight.size(3);
  const int64_t Kw = weight.size(4);
  TORCH_CHECK(Kd == Kh && Kh == Kw, "Only square (cubic) kernels are supported");
  const int64_t K = Kd;

  const int64_t Dout = (D - 1) * stride - 2 * padding + K + output_padding;
  const int64_t Hout = (H - 1) * stride - 2 * padding + K + output_padding;
  const int64_t Wout = (W - 1) * stride - 2 * padding + K + output_padding;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  const float* b_ptr = nullptr;
  torch::Tensor b_c;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.is_cuda() && b_c.scalar_type() == at::kFloat, "bias must be CUDA float32");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == C_out, "bias must be [C_out]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, C_out, Dout, Hout, Wout}, x.options());

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  const float* xp = x_c.data_ptr<float>();
  const float* wp = w_c.data_ptr<float>();
  float* yp = y.data_ptr<float>();

  switch (K) {
    case 1: launch_conv_transpose3d_s1<1>(xp, wp, b_ptr, yp, (int)N, (int)C_in, (int)C_out, (int)D, (int)H, (int)W, (int)Dout, (int)Hout, (int)Wout, (int)padding, stream); break;
    case 2: launch_conv_transpose3d_s1<2>(xp, wp, b_ptr, yp, (int)N, (int)C_in, (int)C_out, (int)D, (int)H, (int)W, (int)Dout, (int)Hout, (int)Wout, (int)padding, stream); break;
    case 3: launch_conv_transpose3d_s1<3>(xp, wp, b_ptr, yp, (int)N, (int)C_in, (int)C_out, (int)D, (int)H, (int)W, (int)Dout, (int)Hout, (int)Wout, (int)padding, stream); break;
    case 4: launch_conv_transpose3d_s1<4>(xp, wp, b_ptr, yp, (int)N, (int)C_in, (int)C_out, (int)D, (int)H, (int)W, (int)Dout, (int)Hout, (int)Wout, (int)padding, stream); break;
    case 5: launch_conv_transpose3d_s1<5>(xp, wp, b_ptr, yp, (int)N, (int)C_in, (int)C_out, (int)D, (int)H, (int)W, (int)Dout, (int)Hout, (int)Wout, (int)padding, stream); break;
    case 6: launch_conv_transpose3d_s1<6>(xp, wp, b_ptr, yp, (int)N, (int)C_in, (int)C_out, (int)D, (int)H, (int)W, (int)Dout, (int)Hout, (int)Wout, (int)padding, stream); break;
    case 7: launch_conv_transpose3d_s1<7>(xp, wp, b_ptr, yp, (int)N, (int)C_in, (int)C_out, (int)D, (int)H, (int)W, (int)Dout, (int)Hout, (int)Wout, (int)padding, stream); break;
    default:
      TORCH_CHECK(false, "Unsupported kernel size K=", K, " (supported: 1..7)");
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv_transpose3d_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution (stride=1, groups=1) implemented with a single
    custom cooperative-tiled CUDA kernel written with CuTe.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias)

        stride_t = _triple(stride)
        padding_t = _triple(padding)
        output_padding_t = _triple(output_padding)
        assert stride_t[0] == stride_t[1] == stride_t[2], "stride must be isotropic"
        assert padding_t[0] == padding_t[1] == padding_t[2], "padding must be isotropic"
        assert output_padding_t[0] == output_padding_t[1] == output_padding_t[2], \
            "output_padding must be isotropic"

        self.stride = int(stride_t[0])
        self.padding = int(padding_t[0])
        self.output_padding = int(output_padding_t[0])
        self.groups = int(groups)
        self._ext = conv_transpose3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_transpose3d_forward(
            x.contiguous(),
            self.conv_transpose3d.weight.contiguous(),
            self.conv_transpose3d.bias,
            self.stride,
            self.padding,
            self.output_padding,
            self.groups,
        )

