  // RB_W adjacent outputs along W, so one shared weight value feeds RB_W FMAs.
  const int td  = tid / (TH * TWT);
  const int th  = (tid / TWT) % TH;
  const int tw  = tid % TWT;
  const int lw0 = tw * RB_W;
