  const int base_d = d0 + padding - (K - 1);
  const int base_h = h0 + padding - (K - 1);
  const int base_w = w0 + padding - (K - 1);
  // Stage weights (ic, oc0..oc0+OC_TILE) and the haloed input tile for
  // input channel ic into shared-memory buffer `buf` (zero-filled outside).
  auto stage_tile = [&](int ic, int buf) {
    Tensor sW = make_sW(buf);
    #pragma unroll
    for (int o = 0; o < OC_TILE; ++o) {
      const int oc = oc0 + o;
      for (int k = tid; k < K3; k += THREADS) {
        float wv = 0.0f;
        if (oc < C_out) {
          int kd = k / K2;
          int r  = k - kd * K2;
          int kh = r / K;
          int kw = r - kh * K;
          wv = mW(ic, oc, kd, kh, kw);
